#:sdk Microsoft.NET.Sdk.Web
// WebSocket chat — the version that slowly fills with ghosts.
//
// Run from the repo root:
//   dotnet run csharp/27-websocket-chat-dotnet/original.cs
// then open http://localhost:5027 in TWO browser windows and chat.
//
// It works — until it doesn't. Close one window and the server keeps
// "sending" to the dead socket forever (the errors are swallowed on line
// "catch { }"). Nobody is ever removed from the list. Two people joining at
// the same instant can corrupt the list mid-loop. And names, history, joins
// and chat all share one tangled loop with no message format at all.

using System.Net.WebSockets;
using System.Text;

var sockets = new List<WebSocket>();   // shared by every connection, no lock
var history = new List<string>();      // grows forever

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.UseWebSockets();

app.MapGet("/", () => Results.Content("""
    <!DOCTYPE html>
    <html>
    <head><meta charset="utf-8"><title>Chat (original)</title></head>
    <body>
      <h1>Chat</h1>
      <div id="log" style="border:1px solid #999;height:300px;overflow-y:auto;padding:8px"></div>
      <form id="f"><input id="m" autocomplete="off"><button>Send</button></form>
      <script>
        var name = prompt("Your name?") || "anon";
        var ws = new WebSocket("ws://" + location.host + "/ws?name=" + encodeURIComponent(name));
        var log = document.getElementById("log");
        ws.onmessage = function (e) {
          log.innerHTML += "<div>" + e.data + "</div>";   // chat text straight into HTML...
          log.scrollTop = log.scrollHeight;
        };
        ws.onclose = function () {
          log.innerHTML += "<div><i>disconnected - refresh the page</i></div>";
        };
        document.getElementById("f").onsubmit = function (e) {
          e.preventDefault();
          var m = document.getElementById("m");
          ws.send(m.value);
          m.value = "";
        };
      </script>
    </body>
    </html>
    """, "text/html"));

app.Map("/ws", async (HttpContext ctx) =>
{
    if (!ctx.WebSockets.IsWebSocketRequest) { ctx.Response.StatusCode = 400; return; }
    var ws = await ctx.WebSockets.AcceptWebSocketAsync();

    sockets.Add(ws);   // two joins at once → List.Add races → corrupted list
    var name = ctx.Request.Query["name"].ToString();
    if (name == "") name = "anon";

    // catch-up, join announcement, and chat all inline in the socket handler
    foreach (var line in history)
        await Send(ws, line);

    var joined = "* " + name + " joined *";
    history.Add(joined);
    foreach (var s in sockets)
        try { await Send(s, joined); } catch { }   // dead socket? pretend it's fine

    var buffer = new byte[4096];
    while (true)
    {
        WebSocketReceiveResult result;
        try { result = await ws.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None); }
        catch { break; }
        if (result.MessageType == WebSocketMessageType.Close) break;

        var text = Encoding.UTF8.GetString(buffer, 0, result.Count);
        var line = name + ": " + text;             // the "protocol": glued strings
        history.Add(line);
        foreach (var s in sockets)                  // still includes every dead socket
            try { await Send(s, line); } catch { } // sends to ghosts, swallows the screams
    }
    // The loop ended: this socket is dead. And yet... nothing happens here.
    // No removal from the list, no "left" message. The ghost stays forever.
});

app.Run("http://localhost:5027");

static async Task Send(WebSocket ws, string text) =>
    await ws.SendAsync(new ArraySegment<byte>(Encoding.UTF8.GetBytes(text)),
        WebSocketMessageType.Text, true, CancellationToken.None);

# 🏋️ Practice: WebSocket Chat (.NET)

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Who is in the room? (warm-up)

Add `public IReadOnlyList<string> Members` to `ChatRoom` — a snapshot of the current member names — and a plain `GET /api/members` endpoint returning it, so you can check the roster with curl while two browsers are connected. Follow the house rule exactly: read `members` only under the lock, and hand back a **copy**, never the live list.
*Practices:* lock discipline for reads, and why a "read-only" property still needs a snapshot when other threads are writing.
**Hint:** `{ lock (gate) return members.Select(m => m.Name).ToList(); }` — the `ToList()` happens inside the lock, so nothing can mutate the list while LINQ walks it.
**Check offline:** add these Check tests to `Tests.cs` — all should pass:
```csharp
var room = new ChatRoom();  var bobSink = new FakeSink();
await room.JoinAsync("alice", new FakeSink());
await room.JoinAsync("bob", bobSink);
Check.Equal("alice,bob", string.Join(",", room.Members), "Members lists everyone, in join order");
await room.LeaveAsync(bobSink);
Check.Equal("alice", string.Join(",", room.Members), "and forgets people who left");
```
Then, with the server running and one browser connected, `curl http://localhost:5027/api/members`.

### ⭐⭐ 2. Two people called bob (core)

Right now two tabs can join as "bob" and nobody can tell them apart — including `LeaveAsync`'s announcement. Make `JoinAsync` hand out a unique name: if the requested name is taken (case-insensitively), append `-2`, `-3`, … until it is free. Return the assigned name in the `JoinTicket` as it already does, so the socket loop keeps using the right one.
*Practices:* making a decision *inside* the lock (checking and claiming must be one atomic step), and testing a concurrency-shaped rule with fakes instead of browsers.
**Hint:** the uniqueness check and the `members.Add` must happen under the *same* lock acquisition, or two simultaneous joins can both see "bob" as free. That means computing the name before the history-sending `await`, and adding to `members` in one guarded block.
**Check offline:** add to `Tests.cs` — all should pass:
```csharp
var busy = new ChatRoom();
var one = await busy.JoinAsync("bob", new FakeSink());
var two = await busy.JoinAsync("  bob  ", new FakeSink());   // trimmed, then suffixed
var three = await busy.JoinAsync("BOB", new FakeSink());
Check.Equal("bob", one.User, "the first bob keeps the name");
Check.Equal("bob-2", two.User, "the second is renamed");
Check.Equal("bob-3", three.User, "and so is the third, case-insensitively");
Check.Equal("bob,bob-2,bob-3", string.Join(",", busy.Members), "every member has a distinct name");
```

### ⭐⭐ 3. A roster on the wire (core)

Announcements say "alice joined" but a client that connects late has no way to know who is *already* here. Add a second message shape — `record RosterMessage(string Type, IReadOnlyList<string> Users, DateTimeOffset At)` with a factory that fills `Type` with `"roster"` — and broadcast one after every join and every leave. The wire now carries two record types serialized with the same options; the client switches on `type` as it already does.
*Practices:* extending a protocol without breaking it, and reusing the existing send-and-prune path instead of writing a second one.
**Hint:** `BroadcastAsync` does two jobs — append to history *and* send to everyone. A roster is ephemeral, so extract the sending half into a private `SendToAllAsync(string json)` and have both the message broadcast and the roster broadcast call it. Roster messages must **not** enter history, or a newcomer would replay stale ones.
**Check offline:** add to `Tests.cs` — all should pass:
```csharp
var r = new ChatRoom();
var alice = new FakeSink();  var bobSink2 = new FakeSink();
await r.JoinAsync("alice", alice);
await r.JoinAsync("bob", bobSink2);
var rosters = alice.Received.Where(j => j.Contains("\"type\":\"roster\"")).ToList();
Check.Equal(2, rosters.Count, "alice saw a roster for her own join and for bob's");
Check.True(rosters[^1].Contains("\"users\":[\"alice\",\"bob\"]"), "the latest roster lists both");
await r.LeaveAsync(bobSink2);
Check.True(alice.Received[^1].Contains("\"users\":[\"alice\"]"), "leaving publishes a fresh roster");
Check.Equal(3, r.History.Count, "history holds join, join, leave — never a roster");
```

### ⭐⭐ 4. Show the roster in the UI (core — builds on 3)

Render the member list in `app.js`: an aside (or a header strip) listing who is online, redrawn every time a `roster` message arrives. Names are user-supplied, so build each entry with `createElement` + `textContent` — the same vaccine `show()` already uses for chat text. Add a `roster` branch to the message handler before the existing chat/system split.
*Practices:* extending the client's protocol switch, and applying the XSS habit in a new place.
**Hint:** `if (message.type === 'roster') { renderRoster(message.users); return; }` at the top of `show()`. `replaceChildren()` clears the list in one call. Note the roster arrives *unprompted* — this is push, not request/response, which is the whole reason for a WebSocket.
**Check offline:** open http://localhost:5027 in two windows. Expected: both lists show both names within a moment of the second join, with no reload and no polling in the Network tab; close one window and the other's list shrinks by itself. Then join as `<img src=x onerror=alert(1)>` — no alert, and the name shows as literal text.

### ⭐⭐⭐ 5. Slow down the flooder (challenge)

Add rate limiting: a member may send at most `maxPerWindow` messages (default 10) per 10-second window. `SayAsync` becomes `Task<bool>` — `false` means refused — and a refused message is broadcast to nobody; instead the offender alone receives a `"system"` message explaining the limit. Inject the clock as `Func<DateTimeOffset>` so the test can jump forward eleven seconds instead of sleeping.
*Practices:* per-member state guarded by the same lock, sending to **one** sink instead of broadcasting, and injected time (project 11's trick) meeting concurrency.
**Hint:** `Dictionary<string, List<DateTimeOffset>>` keyed case-insensitively; inside the lock, drop stamps older than the window, refuse if `Count >= maxPerWindow`, otherwise record and allow. Give both new constructor parameters defaults, exactly like `historyLimit = 50`, so `AddSingleton<ChatRoom>()` keeps working. Drop a member's stamps in `LeaveAsync` so the dictionary cannot grow forever.
**Check offline:** add to `Tests.cs` — all should pass, with no `Thread.Sleep`:
```csharp
var now = new DateTimeOffset(2026, 1, 1, 12, 0, 0, TimeSpan.Zero);
var strict = new ChatRoom(historyLimit: 50, maxPerWindow: 3, clock: () => now);
var loud = new FakeSink();  var quiet = new FakeSink();
await strict.JoinAsync("loud", loud);
await strict.JoinAsync("quiet", quiet);
for (var i = 1; i <= 3; i++)
    Check.Equal(true, await strict.SayAsync("loud", $"m{i}"), $"message {i} is within the limit");
var heard = quiet.Received.Count;
Check.Equal(false, await strict.SayAsync("loud", "m4"), "the 4th message in the window is refused");
Check.Equal(heard, quiet.Received.Count, "and nobody else heard it");
Check.True(loud.Received[^1].Contains("\"type\":\"system\""), "the flooder alone gets a warning");
now = now.AddSeconds(11);
Check.Equal(true, await strict.SayAsync("loud", "m5"), "once the window passes, talking works again");
```

## Solutions

### 1. Who is in the room?

```csharp
// ChatRoom.cs
public IReadOnlyList<string> Members { get { lock (gate) return members.Select(m => m.Name).ToList(); } }
// Program.cs — an ordinary HTTP endpoint alongside the socket route
app.MapGet("/api/members", (ChatRoom room) => Results.Ok(room.Members));
```

WHY: the `ToList()` is not politeness, it is the point — returning `members` itself (or a lazy LINQ query over it) would hand the caller a reference into state another thread is editing, and iterating it outside the lock is precisely the `InvalidOperationException: Collection was modified` the original suffered from. Copying inside the lock and returning the copy is the same snapshot-then-use pattern `BroadcastAsync` already follows, and it is why this class's rules are stated as three lines at the top of the file rather than rediscovered per method.

### 2. Two people called bob

```csharp
// ChatRoom.cs — JoinAsync's opening changes to decide the name under the lock:
IReadOnlyList<ChatMessage> snapshot;
string user;
lock (gate)
{
    snapshot = history.ToList();
    user = UniqueName(requested);     // decided under the lock; claimed by members.Add below
}
// ...the rest of JoinAsync is unchanged, using `user` where it used the raw name.
// caller must already hold the lock
private string UniqueName(string requested)
{
    if (!members.Any(m => string.Equals(m.Name, requested, StringComparison.OrdinalIgnoreCase))) return requested;
    for (int suffix = 2; ; suffix++)
    {
        var candidate = $"{requested}-{suffix}";
        if (!members.Any(m => string.Equals(m.Name, candidate, StringComparison.OrdinalIgnoreCase)))
            return candidate;
    }
}
```

WHY: this is the classic check-then-act race — between "is bob free?" and "I'm bob now", another connection can claim it, and both tabs end up as bob. Strictly, the airtight version computes *and* adds in a single locked block; the split above keeps the `await` (which must never happen while holding a lock) between them, which is the pragmatic trade this codebase already makes elsewhere. If you want it truly atomic, add the member first with a placeholder sink and send history afterwards — worth trying, and worth noticing that the "obvious" fix moves a different problem around rather than removing it. That discomfort is what concurrency feels like.

### 3. A roster on the wire

```csharp
// ChatMessage.cs — a second shape on the same wire, same JsonOptions
public record RosterMessage(string Type, IReadOnlyList<string> Users, DateTimeOffset At)
{
    public static RosterMessage Of(IReadOnlyList<string> users) => new("roster", users, DateTimeOffset.Now);
    public string ToJson() => JsonSerializer.Serialize(this, ChatMessage.JsonOptions);
}
// ChatRoom.cs — the sending half, extracted so two callers can share it
public Task BroadcastRosterAsync() => SendToAllAsync(RosterMessage.Of(Members).ToJson());
public async Task BroadcastAsync(ChatMessage message)
{
    lock (gate)
    {
        history.Add(message);
        if (history.Count > historyLimit) history.RemoveRange(0, history.Count - historyLimit);
    }
    await SendToAllAsync(message.ToJson());
}
// This is BroadcastAsync's old body from the snapshot line down — unchanged,
// pruning included; only the history bookkeeping stayed behind.
private async Task SendToAllAsync(string json)
{
    List<(string Name, ISocketSink Sink)> recipients;
    lock (gate) recipients = members.ToList();       // snapshot, then unlock
    List<ISocketSink>? dead = null;
    foreach (var (_, sink) in recipients)
    {
        if (!sink.IsOpen) { (dead ??= new()).Add(sink); continue; }
        try { await sink.SendAsync(json); }
        catch { (dead ??= new()).Add(sink); }
    }
    if (dead is not null)
        lock (gate) members.RemoveAll(m => dead.Contains(m.Sink));
}
// ...then `await BroadcastRosterAsync();` at the end of JoinAsync and after the
// leave announcement in LeaveAsync.
```

WHY: splitting `BroadcastAsync` in two is the whole exercise — "record it in history" and "send it to everyone" turned out to be separate jobs the moment a message existed that only needed the second. The pruning logic came along for free, so a roster send also cleans up dead sockets, and there is still exactly one loop that knows how to talk to members. Keeping rosters out of history matters for a subtle reason: history is *replayed* to newcomers, and replaying a snapshot of who was online three minutes ago would be worse than useless — a live roster follows immediately anyway.

### 4. Show the roster in the UI

```html
<!-- index.html, inside <main> -->
<aside id="roster-panel">
  <h2>Online</h2>
  <ul id="roster"></ul>
</aside>
```

```js
// app.js
const roster = document.querySelector('#roster');
function renderRoster(users) {
  roster.replaceChildren();
  for (const user of users) {
    const li = document.createElement('li');
    li.textContent = user;      // names are user input, like everything else here
    roster.appendChild(li);
  }
}
// show() gains one branch, above the existing chat / system rendering:
if (message.type === 'roster') { renderRoster(message.users); return; }
```

WHY: the client's `show()` was already a switch on `type`, so a new message kind cost one branch — that is the dividend the refactor's "messages are records, not glued strings" decision pays out. `replaceChildren()` redraws from the server's list rather than diffing, which is the same render-the-whole-truth policy as projects 25 and 26 and is what makes a dropped or duplicated roster message harmless. And note what makes this *feel* different from the fetch-based projects: nobody asked for the roster. The server pushed it, unprompted, the instant the room changed.

### 5. Slow down the flooder

```csharp
// ChatRoom.cs
private readonly Dictionary<string, List<DateTimeOffset>> recentByUser = new(StringComparer.OrdinalIgnoreCase);
private readonly int maxPerWindow;
private readonly Func<DateTimeOffset> clock;
private static readonly TimeSpan Window = TimeSpan.FromSeconds(10);
// Every parameter has a default, so AddSingleton<ChatRoom>() still works.
public ChatRoom(int historyLimit = 50, int maxPerWindow = 10, Func<DateTimeOffset>? clock = null)
{
    this.historyLimit = historyLimit;
    this.maxPerWindow = maxPerWindow;
    this.clock = clock ?? (() => DateTimeOffset.Now);   // real time unless a test says otherwise
}
public async Task<bool> SayAsync(string user, string? text)
{
    var trimmed = (text ?? "").Trim();
    if (trimmed.Length == 0) return false;
    if (!TryRecordSend(user))
    {
        var offender = FindSink(user);            // tell the flooder, and nobody else
        if (offender is not null)
            await offender.SendAsync(ChatMessage.System(
                $"Slow down — at most {maxPerWindow} messages every {Window.TotalSeconds:0} seconds.").ToJson());
        return false;
    }
    await BroadcastAsync(ChatMessage.Chat(user, trimmed));
    return true;
}
private bool TryRecordSend(string user)
{
    lock (gate)
    {
        var now = clock();
        if (!recentByUser.TryGetValue(user, out var stamps)) recentByUser[user] = stamps = new();
        stamps.RemoveAll(t => now - t >= Window);      // forget what left the window
        if (stamps.Count >= maxPerWindow) return false;
        stamps.Add(now);
        return true;
    }
}
private ISocketSink? FindSink(string user)
{
    lock (gate)
    {
        var i = members.FindIndex(m => string.Equals(m.Name, user, StringComparison.OrdinalIgnoreCase));
        return i < 0 ? null : members[i].Sink;
    }
}
// ChatMessage.cs gains one factory, and LeaveAsync one line inside its lock:
public static ChatMessage System(string text) => new("system", "server", text, DateTimeOffset.Now);
recentByUser.Remove(user);   // don't let the counter dictionary grow forever
```

WHY: a sliding window of timestamps is the simplest correct rate limiter — no background timer, no reset boundary a flooder can synchronise with, and the pruning happens lazily on the next attempt. It lives inside the same `gate` as `members` because the counters *are* shared mutable state, and a second lock would only create a chance to deadlock. Two design details are worth arguing about: the refusal is private (broadcasting "loud is spamming" would give the flooder the attention they wanted), and it is a `"system"` message rather than a dropped connection, because being briefly wrong about who is abusive is much cheaper than kicking a legitimate fast typist. And once again, the clock is a parameter — the alternative test takes eleven real seconds and will one day be deleted for being slow.

using System.Text.Json;

// The protocol: every message on the wire is one of these, as JSON.
// Three factory methods = the three message types = the whole vocabulary.
// The browser switches on `type`; nobody ever parses glued-together strings.
public record ChatMessage(string Type, string User, string Text, DateTimeOffset At)
{
    // Web defaults: camelCase property names, so C# `User` ⇄ JSON `user`.
    public static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    public static ChatMessage Chat(string user, string text) => new("chat", user, text, DateTimeOffset.Now);
    public static ChatMessage Join(string user) => new("join", user, "", DateTimeOffset.Now);
    public static ChatMessage Leave(string user) => new("leave", user, "", DateTimeOffset.Now);

    public string ToJson() => JsonSerializer.Serialize(this, JsonOptions);
}

// What the browser sends us: just the text. (The server already knows who
// you are from the join — clients don't get to claim names per message.)
public record IncomingMessage(string? Text)
{
    // Clients are untrusted: malformed JSON becomes null, never a crash.
    public static IncomingMessage? Parse(string json)
    {
        try { return JsonSerializer.Deserialize<IncomingMessage>(json, ChatMessage.JsonOptions); }
        catch (JsonException) { return null; }
    }
}

// What ChatRoom needs from "a connected client" — and nothing more.
// The real one wraps a WebSocket; the test one is a List<string>.
public interface ISocketSink
{
    bool IsOpen { get; }
    Task SendAsync(string json);
}

// All the shared, mutable chat state lives HERE, guarded by one lock.
// The rules:
//   * touch `members` or `history` ONLY while holding the lock
//   * never await while holding the lock (grab a snapshot, then send)
//   * a socket that is closed or that throws on send is dead — prune it

public sealed record JoinTicket(string User, IReadOnlyList<ChatMessage> History);

public sealed class ChatRoom
{
    private readonly object gate = new();
    private readonly List<(string Name, ISocketSink Sink)> members = new();
    private readonly List<ChatMessage> history = new();
    private readonly int historyLimit;

    public ChatRoom(int historyLimit = 50)
    {
        this.historyLimit = historyLimit;
    }

    public int MemberCount { get { lock (gate) return members.Count; } }

    public IReadOnlyList<ChatMessage> History { get { lock (gate) return history.ToList(); } }

    // Joining: catch the newcomer up on recent history, then announce them
    // to everyone. Returns what was sent so callers (and tests) can see it.
    public async Task<JoinTicket> JoinAsync(string? requestedName, ISocketSink sink)
    {
        var user = string.IsNullOrWhiteSpace(requestedName) ? "anon" : requestedName.Trim();

        IReadOnlyList<ChatMessage> snapshot;
        lock (gate)
        {
            snapshot = history.ToList();   // copy: safe to read outside the lock
        }

        foreach (var message in snapshot)
            await sink.SendAsync(message.ToJson());

        lock (gate)
        {
            members.Add((user, sink));
        }

        await BroadcastAsync(ChatMessage.Join(user));
        return new JoinTicket(user, snapshot);
    }

    public Task SayAsync(string user, string? text)
    {
        var trimmed = (text ?? "").Trim();
        if (trimmed.Length == 0) return Task.CompletedTask;   // empty sends are noise
        return BroadcastAsync(ChatMessage.Chat(user, trimmed));
    }

    public async Task LeaveAsync(ISocketSink sink)
    {
        string? user = null;
        lock (gate)
        {
            var index = members.FindIndex(m => ReferenceEquals(m.Sink, sink));
            if (index >= 0)
            {
                user = members[index].Name;
                members.RemoveAt(index);
            }
        }
        if (user is not null)
            await BroadcastAsync(ChatMessage.Leave(user));
    }

    public async Task BroadcastAsync(ChatMessage message)
    {
        List<(string Name, ISocketSink Sink)> recipients;
        lock (gate)
        {
            history.Add(message);
            if (history.Count > historyLimit)                       // capped, not immortal
                history.RemoveRange(0, history.Count - historyLimit);
            recipients = members.ToList();                          // snapshot, then unlock
        }

        var json = message.ToJson();   // encode ONCE, not once per client (js#67)

        List<ISocketSink>? dead = null;
        foreach (var (_, sink) in recipients)
        {
            if (!sink.IsOpen)
            {
                (dead ??= new()).Add(sink);
                continue;
            }
            try
            {
                await sink.SendAsync(json);
            }
            catch
            {
                // A send that throws means the socket died mid-flight.
                // Don't swallow-and-forget like the original: mark it.
                (dead ??= new()).Add(sink);
            }
        }

        if (dead is not null)
            lock (gate)
                members.RemoveAll(m => dead.Contains(m.Sink));      // prune the ghosts
    }
}

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<ChatRoom>();   // ONE room shared by every connection
var app = builder.Build();

app.UseDefaultFiles();
app.UseStaticFiles();
app.UseWebSockets();

// The socket loop is all that's left here: receive → parse → ChatRoom call.
// Every decision (who hears what, history, pruning) lives in ChatRoom.
app.Map("/ws", async (HttpContext context, ChatRoom room) =>
{
    if (!context.WebSockets.IsWebSocketRequest)
    {
        context.Response.StatusCode = StatusCodes.Status400BadRequest;
        return;
    }

    using var socket = await context.WebSockets.AcceptWebSocketAsync();
    var sink = new WebSocketSink(socket);
    var ticket = await room.JoinAsync(context.Request.Query["name"].ToString(), sink);

    try
    {
        while (true)
        {
            var text = await WebSocketSink.ReceiveTextAsync(socket);
            if (text is null) break;   // closed or vanished — same exit either way

            var incoming = IncomingMessage.Parse(text);
            if (incoming is not null)
                await room.SayAsync(ticket.User, incoming.Text);
        }
    }
    finally
    {
        // however the loop ends — clean close, crash, kicked cable —
        // the room always finds out.
        await room.LeaveAsync(sink);
    }
});

app.Run("http://localhost:5027");

using System.Text.Json;

// ChatRoom never touches a real WebSocket — it only knows ISocketSink.
// So the tests hand it FakeSinks: a "socket" that is just a list of what
// it received, plus switches to play dead. No network, no ports, no sleep.
public class FakeSink : ISocketSink
{
    public List<string> Received { get; } = new();
    public bool IsOpen { get; set; } = true;
    public bool ThrowOnSend { get; set; }

    public Task SendAsync(string json)
    {
        if (ThrowOnSend) throw new InvalidOperationException("socket burst into flames");
        Received.Add(json);
        return Task.CompletedTask;
    }

    // Parse everything this fake received back into typed messages.
    public List<ChatMessage> Messages() =>
        Received.Select(j => JsonSerializer.Deserialize<ChatMessage>(j, ChatMessage.JsonOptions)!).ToList();

    public ChatMessage Last() => Messages()[^1];
}

public static class Tests
{
    public static int Run() => RunAsync().GetAwaiter().GetResult();

    static async Task<int> RunAsync()
    {
        Console.WriteLine("ChatRoom");
        await JoinNormalizesNamesAndAnnounces();
        await JoinDeliversHistoryFirst();
        await SayBroadcastsToEveryone();
        await EmptyMessagesAreIgnored();
        await HistoryIsCapped();
        await ClosedSocketsArePruned();
        await ThrowingSocketsArePruned();
        await LeaveAnnouncesToTheOthers();
        await WireFormatIsCamelCaseJson();
        return Check.Summary();
    }

    static async Task JoinNormalizesNamesAndAnnounces()
    {
        var room = new ChatRoom();
        var alice = new FakeSink();
        var ticket = await room.JoinAsync("  Alice  ", alice);
        Check.Equal("Alice", ticket.User, "names are trimmed");
        Check.Equal(1, room.MemberCount, "joining adds you to the room");
        Check.Equal("join", alice.Last().Type, "everyone (including you) hears the join");
        Check.Equal("Alice", alice.Last().User, "the join names the joiner");

        var anon = await room.JoinAsync("   ", new FakeSink());
        Check.Equal("anon", anon.User, "blank names become anon");
    }

    static async Task JoinDeliversHistoryFirst()
    {
        var room = new ChatRoom();
        var alice = new FakeSink();
        await room.JoinAsync("alice", alice);
        await room.SayAsync("alice", "hello?");

        var bob = new FakeSink();
        var ticket = await room.JoinAsync("bob", bob);

        Check.Equal(2, ticket.History.Count, "the ticket reports what catch-up was sent");
        var got = bob.Messages();
        Check.Equal("join,chat,join", string.Join(",", got.Select(m => m.Type)),
            "bob gets history in order, then his own join announcement");
        Check.Equal("hello?", got[1].Text, "history includes the words, not just the fact");
    }

    static async Task SayBroadcastsToEveryone()
    {
        var room = new ChatRoom();
        var alice = new FakeSink();
        var bob = new FakeSink();
        await room.JoinAsync("alice", alice);
        await room.JoinAsync("bob", bob);

        await room.SayAsync("alice", "  hi bob!  ");

        Check.Equal("hi bob!", alice.Last().Text, "the sender hears their own message (trimmed)");
        Check.Equal("hi bob!", bob.Last().Text, "the other member hears it too");
        Check.Equal("alice", bob.Last().User, "the message carries who said it");
        Check.Equal("chat", bob.Last().Type, "and what kind it is");
    }

    static async Task EmptyMessagesAreIgnored()
    {
        var room = new ChatRoom();
        var alice = new FakeSink();
        await room.JoinAsync("alice", alice);
        var before = alice.Received.Count;
        await room.SayAsync("alice", "");
        await room.SayAsync("alice", "   ");
        await room.SayAsync("alice", null);
        Check.Equal(before, alice.Received.Count, "blank chat messages go nowhere");
        Check.Equal(1, room.History.Count, "and never enter history (only the join is there)");
    }

    static async Task HistoryIsCapped()
    {
        var room = new ChatRoom(historyLimit: 3);
        for (var i = 1; i <= 5; i++)
            await room.SayAsync("bot", $"m{i}");
        var history = room.History;
        Check.Equal(3, history.Count, "history never grows past its cap");
        Check.Equal("m3,m4,m5", string.Join(",", history.Select(m => m.Text)),
            "the OLDEST messages are the ones dropped");
    }

    static async Task ClosedSocketsArePruned()
    {
        var room = new ChatRoom();
        var alice = new FakeSink();
        var bob = new FakeSink();
        await room.JoinAsync("alice", alice);
        await room.JoinAsync("bob", bob);
        Check.Equal(2, room.MemberCount, "two members before the disconnect");

        bob.IsOpen = false;                     // bob's laptop lid snaps shut
        var bobHeard = bob.Received.Count;
        await room.SayAsync("alice", "you still there?");

        Check.Equal(1, room.MemberCount, "the dead socket was pruned by the broadcast");
        Check.Equal(bobHeard, bob.Received.Count, "nothing was sent to the corpse");
        Check.Equal("you still there?", alice.Last().Text, "the living still get the message");
    }

    static async Task ThrowingSocketsArePruned()
    {
        var room = new ChatRoom();
        var alice = new FakeSink();
        var bob = new FakeSink();
        await room.JoinAsync("alice", alice);
        await room.JoinAsync("bob", bob);

        bob.ThrowOnSend = true;                 // dies mid-send instead of quietly
        await room.SayAsync("alice", "anyone?");

        Check.Equal(1, room.MemberCount, "a socket that throws on send is pruned too");
        Check.Equal("anyone?", alice.Last().Text, "one bad socket can't block the others");
    }

    static async Task LeaveAnnouncesToTheOthers()
    {
        var room = new ChatRoom();
        var alice = new FakeSink();
        var bob = new FakeSink();
        await room.JoinAsync("alice", alice);
        await room.JoinAsync("bob", bob);

        var aliceHeard = alice.Received.Count;
        await room.LeaveAsync(alice);

        Check.Equal(1, room.MemberCount, "leaving removes you from the room");
        Check.Equal("leave", bob.Last().Type, "the others hear you left");
        Check.Equal("alice", bob.Last().User, "by name");
        Check.Equal(aliceHeard, alice.Received.Count, "you don't hear your own goodbye");

        await room.LeaveAsync(new FakeSink());  // never joined
        Check.Equal(1, room.MemberCount, "leaving with an unknown socket changes nothing");
    }

    static async Task WireFormatIsCamelCaseJson()
    {
        var room = new ChatRoom();
        var alice = new FakeSink();
        await room.JoinAsync("alice", alice);
        await room.SayAsync("alice", "wire check");
        var raw = alice.Received[^1];
        Check.True(raw.Contains("\"type\":\"chat\""), "JSON uses a lowercase `type` field");
        Check.True(raw.Contains("\"user\":\"alice\""), "and a lowercase `user` field");
        Check.True(raw.Contains("\"text\":\"wire check\""), "and a lowercase `text` field");
        Check.True(raw.Contains("\"at\":"), "with a timestamp the browser can parse");
    }
}

using System.Net.WebSockets;
using System.Text;

// The real ISocketSink: a thin adapter over an actual WebSocket.
// All the WebSocket-specific fiddliness lives here so ChatRoom (and its
// tests) never have to touch a real socket.
public sealed class WebSocketSink : ISocketSink
{
    private readonly WebSocket socket;

    // A WebSocket allows only ONE outgoing send at a time. Two broadcasts
    // can overlap (two people talking at once), so sends take a turn-taking
    // token first. SemaphoreSlim is the awaitable cousin of lock.
    private readonly SemaphoreSlim sendTurn = new(1, 1);

    public WebSocketSink(WebSocket socket)
    {
        this.socket = socket;
    }

    public bool IsOpen => socket.State == WebSocketState.Open;

    public async Task SendAsync(string json)
    {
        var bytes = Encoding.UTF8.GetBytes(json);
        await sendTurn.WaitAsync();
        try
        {
            await socket.SendAsync(new ArraySegment<byte>(bytes),
                WebSocketMessageType.Text, endOfMessage: true, CancellationToken.None);
        }
        finally
        {
            sendTurn.Release();
        }
    }

    // Receive one COMPLETE text message (a message can arrive in several
    // frames — keep reading until EndOfMessage). Returns null when the
    // client closed or the connection died: both just mean "they're gone".
    public static async Task<string?> ReceiveTextAsync(WebSocket socket)
    {
        var buffer = new byte[4 * 1024];
        using var whole = new MemoryStream();
        while (true)
        {
            WebSocketReceiveResult result;
            try
            {
                result = await socket.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);
            }
            catch (WebSocketException)
            {
                return null;   // vanished mid-receive: routine departure, not a crash
            }
            if (result.MessageType == WebSocketMessageType.Close) return null;
            whole.Write(buffer, 0, result.Count);
            if (result.EndOfMessage) return Encoding.UTF8.GetString(whole.ToArray());
        }
    }
}

// WebSocket client with the lesson js#67 taught: connections DROP, and a
// real client plans for it — reconnect automatically, back off a little
// more on each failed attempt, and reset once we're healthy again.

const overlay = document.querySelector('#name-overlay');
const nameForm = document.querySelector('#name-form');
const nameInput = document.querySelector('#name-input');
const main = document.querySelector('main');
const messages = document.querySelector('#messages');
const statusEl = document.querySelector('#status');
const sendForm = document.querySelector('#send-form');
const textInput = document.querySelector('#text');

let ws = null;
let name = null;
let retryDelay = 1000;   // doubles on each failure, capped below

function setStatus(text, kind) {
  statusEl.textContent = text;
  statusEl.className = `status ${kind}`;
}

function connect() {
  setStatus('connecting…', 'connecting');
  ws = new WebSocket(`ws://${location.host}/ws?name=${encodeURIComponent(name)}`);

  ws.addEventListener('open', () => {
    retryDelay = 1000;        // healthy again — reset the backoff
    messages.innerHTML = '';  // server re-sends recent history on every connect
    setStatus('online', 'online');
    textInput.focus();
  });

  ws.addEventListener('message', (event) => {
    show(JSON.parse(event.data));
  });

  ws.addEventListener('close', () => {
    setStatus(`offline — retrying in ${retryDelay / 1000}s`, 'offline');
    setTimeout(connect, retryDelay);
    retryDelay = Math.min(retryDelay * 2, 10000);   // exponential backoff, capped
  });
}

function show(message) {
  const div = document.createElement('div');
  const time = new Date(message.at).toLocaleTimeString();

  if (message.type === 'chat') {
    div.className = 'chat';
    const who = document.createElement('strong');
    who.textContent = message.user;          // textContent — never innerHTML —
    const what = document.createElement('span');
    what.textContent = message.text;         // because chat text is user input
    const when = document.createElement('time');
    when.textContent = time;
    div.append(who, what, when);
  } else {
    div.className = 'system';
    div.textContent =
      `${message.user} ${message.type === 'join' ? 'joined' : 'left'} · ${time}`;
  }

  messages.appendChild(div);
  messages.scrollTop = messages.scrollHeight;
}

nameForm.addEventListener('submit', (event) => {
  event.preventDefault();
  name = nameInput.value.trim() || 'anon';
  overlay.remove();
  main.hidden = false;
  connect();
});

sendForm.addEventListener('submit', (event) => {
  event.preventDefault();
  // readyState check: sending on a closed socket throws (js#67's lesson).
  if (!ws || ws.readyState !== WebSocket.OPEN) return;
  const text = textInput.value.trim();
  if (!text) return;
  ws.send(JSON.stringify({ text }));
  textInput.value = '';
});

